/* ── HOME PAGE ── */

.home {
  padding-bottom: var(--space-32);
}

/* ── Hero ── */
.hero {
  min-height: 100dvh;
  display: flex;
  align-items: center;
  position: relative;
  background-image:
    radial-gradient(circle at 20% 50%, rgba(37, 99, 235, 0.03) 0%, transparent 50%),
    radial-gradient(circle at 80% 20%, rgba(37, 99, 235, 0.02) 0%, transparent 40%);
}

.hero::before {
  content: "" / "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.015) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.015) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 70% 60% at 50% 50%, black 30%, transparent 100%);
  pointer-events: none;
}

.hero__inner {
  position: relative;
  z-index: 1;
  padding-block: var(--space-20);
}

.hero__content {
  max-width: 800px;
}

.hero__name {
  font-family: var(--font-display);
  font-size: clamp(4rem, 3rem + 8vw, 10rem);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.05em;
  color: var(--color-text-primary);
  margin-bottom: var(--space-8);
}

.hero__title {
  font-family: var(--font-display);
  font-size: clamp(1.25rem, 1rem + 1.5vw, 1.75rem);
  font-weight: 500;
  color: var(--color-text-secondary);
  letter-spacing: -0.01em;
  margin-bottom: var(--space-3);
}

.hero__domains {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  font-weight: 400;
  color: var(--color-accent-text);
  letter-spacing: 0.02em;
  margin-bottom: var(--space-8);
}

.hero__statement {
  font-size: clamp(1rem, 0.9rem + 0.5vw, 1.2rem);
  max-width: 560px;
  line-height: 1.7;
  color: var(--color-text-secondary);
  margin-bottom: var(--space-10);
}

.hero__ctas {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
  margin-bottom: var(--space-12);
}

.hero__btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 500;
  border-radius: var(--radius-lg);
  transition: all var(--duration-normal) var(--ease-out);
  min-height: 48px;
}

.hero__btn--primary {
  background: var(--color-accent);
  color: var(--white-pure);
}

.hero__btn--primary:hover {
  background: var(--color-accent-hover);
  color: var(--white-pure);
  box-shadow: var(--shadow-blue);
  transform: translateY(-2px);
}

.hero__btn--secondary {
  background: transparent;
  color: var(--color-text-primary);
  border: 1px solid var(--color-border-strong);
}

.hero__btn--secondary:hover {
  color: var(--color-text-primary);
  border-color: var(--color-text-secondary);
  background: var(--color-bg-surface);
  transform: translateY(-2px);
}

.hero__scroll-indicator {
  position: absolute;
  bottom: var(--space-8);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--color-text-tertiary);
}

.hero__scroll-label {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--color-text-tertiary);
}

.hero__scroll-track {
  position: relative;
  width: 42px;
  height: 64px;
  border: 1px solid rgba(148, 163, 184, 0.45);
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.18);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.02);
  overflow: hidden;
}

.hero__scroll-thumb {
  position: absolute;
  left: 50%;
  top: 12px;
  width: 8px;
  height: 16px;
  transform: translateX(-50%);
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(96, 165, 250, 1), rgba(59, 130, 246, 0.6));
  box-shadow: 0 0 18px rgba(59, 130, 246, 0.55);
  animation: scroll-thumb 1.8s ease-in-out infinite;
}

@keyframes scroll-thumb {
  0% {
    opacity: 0;
    transform: translate(-50%, -4px);
  }
  20% {
    opacity: 1;
  }
  80% {
    opacity: 1;
    transform: translate(-50%, 18px);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, 28px);
  }
}

/* ── Section Labels ── */
.section-label {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-text-tertiary);
  margin-bottom: var(--space-4);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.section-label__accent {
  color: var(--color-accent-text);
  font-size: 0.5rem;
}

.section-title {
  font-size: clamp(var(--text-2xl), 1.5rem + 2vw, var(--text-4xl));
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-12);
}

.section-footer {
  margin-top: var(--space-10);
}

.section-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-accent-text);
  transition: gap var(--duration-normal) var(--ease-out);
}

.section-link:hover {
  gap: var(--space-3);
  color: var(--color-accent-hover);
}

/* ── Currently ── */
.currently-section {
  padding-block: var(--space-24);
}

.currently-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-4);
}

.currently-card {
  padding: var(--space-6);
  background: var(--color-bg-elevated);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  transition: all var(--duration-normal) var(--ease-out);
}

.currently-card:hover {
  border-color: var(--color-border-hover);
  transform: translateY(-2px);
}

.currently-card__category {
  display: block;
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent-text);
  margin-bottom: var(--space-3);
}

.currently-card__desc {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* ── Featured Work ── */
.featured-section {
  padding-block: var(--space-24);
}

.featured-list {
  display: flex;
  flex-direction: column;
}

.featured-item {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: var(--space-6);
  align-items: center;
  padding: var(--space-8) 0;
  border-bottom: 1px solid var(--color-border);
  text-decoration: none;
  color: inherit;
  transition: all var(--duration-normal) var(--ease-out);
}

.featured-item:first-child {
  border-top: 1px solid var(--color-border);
}

.featured-item:hover {
  padding-inline: var(--space-6);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-xl);
  margin-inline: calc(-1 * var(--space-6));
}

.featured-item:hover .featured-item__arrow {
  opacity: 1;
  transform: translateX(0);
}

.featured-item:hover .featured-item__title {
  color: var(--color-accent-text);
}

.featured-item__number {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  min-width: 2rem;
}

.featured-item__content {
  min-width: 0;
}

.featured-item__top {
  display: flex;
  gap: var(--space-4);
  align-items: center;
  margin-bottom: var(--space-2);
}

.featured-item__category {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-accent-text);
}

.featured-item__year {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--color-text-muted);
}

.featured-item__title {
  font-size: clamp(var(--text-lg), 1rem + 0.5vw, var(--text-2xl));
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: var(--space-2);
  transition: color var(--duration-fast) var(--ease-out);
}

.featured-item__desc {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-3);
  max-width: 500px;
}

.featured-item__tags {
  display: flex;
  gap: var(--space-2);
  flex-wrap: wrap;
}

.tag {
  display: inline-block;
  padding: 2px var(--space-3);
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  color: var(--color-text-tertiary);
  background: var(--color-bg-surface);
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border);
}

.tag--status {
  color: var(--color-accent-text);
  border-color: rgba(37, 99, 235, 0.2);
  background: var(--color-accent-subtle);
}

.featured-item__arrow {
  color: var(--color-text-tertiary);
  opacity: 0;
  transform: translateX(-8px);
  transition: all var(--duration-normal) var(--ease-out);
}

/* ── Writing ── */
.writing-section {
  padding-block: var(--space-24);
}

.writing-list {
  display: flex;
  flex-direction: column;
}

.writing-item {
  display: block;
  padding: var(--space-6) 0;
  border-bottom: 1px solid var(--color-border);
  text-decoration: none;
  color: inherit;
  transition: all var(--duration-normal) var(--ease-out);
}

.writing-item:first-child {
  border-top: 1px solid var(--color-border);
}

.writing-item:hover {
  padding-inline: var(--space-6);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-xl);
}

.writing-item:hover .writing-item__title {
  color: var(--color-accent-text);
}

.writing-item__meta {
  display: flex;
  gap: var(--space-4);
  margin-bottom: var(--space-2);
}

.writing-item__category,
.writing-item__date {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-text-muted);
}

.writing-item__category {
  color: var(--color-accent-text);
}

.writing-item__title {
  font-size: var(--text-lg);
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: var(--space-2);
  transition: color var(--duration-fast) var(--ease-out);
}

.writing-item__excerpt {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-2);
  max-width: 600px;
}

.writing-item__read {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--color-text-muted);
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .hero__name {
    font-size: clamp(3.5rem, 15vw, 6rem);
  }

  .featured-item {
    grid-template-columns: 1fr;
    gap: var(--space-3);
  }

  .featured-item__number {
    font-size: var(--text-xs);
  }

  .featured-item__arrow {
    display: none;
  }

  .currently-grid {
    grid-template-columns: 1fr;
  }

  .hero__ctas {
    flex-direction: column;
  }

  .hero__btn {
    justify-content: center;
  }
}
